1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>FirstRun: Replay a run</title>
7	<meta name="description" content="Replay a FirstRun share code in the browser: read, plan, run, fix, prove. Nothing leaves your machine.">
8	<meta name="robots" content="noindex">
9	<style>
10	:root{--page:#F5F5F7;--surface:#FBFBFD;--ink:#1D1D1F;--muted:#6E6E73;--accent:#0066CC;--pass:#1F8A3B;--fail:#D70015;--warn:#8A5A00;--hair:rgba(29,29,31,.07);--ease:cubic-bezier(.16,1,.3,1)}
11	*{box-sizing:border-box;margin:0}
12	html{background:var(--page);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%}
13	body{line-height:1.5;font-size:17px;overflow-x:hidden}
14	code,pre,.mono{font-family:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
15	a{color:var(--accent);text-underline-offset:3px}
16	a:focus-visible,button:focus-visible,summary:focus-visible,textarea:focus-visible{outline:3px solid var(--accent);outline-offset:3px;border-radius:8px}
17	main{max-width:860px;margin:0 auto;padding:32px 24px 24px}
18	.wm{font-weight:700;font-size:15px;letter-spacing:-.01em;margin-bottom:40px;display:flex;justify-content:space-between;gap:12px}
19	.wm a{color:var(--muted);text-decoration:none}
20	.wm a:hover{color:var(--ink)}
21	h1{font-size:clamp(30px,6vw,52px);line-height:1.05;letter-spacing:-.035em;font-weight:700;overflow-wrap:anywhere}
22	h2{font-size:22px;letter-spacing:-.02em;font-weight:700;margin-bottom:14px}
23	.lede{font-size:19px;color:var(--muted);max-width:34em;margin-top:12px}
24	button{font:inherit;font-weight:600;font-size:16px;background:var(--accent);color:#fff;border:0;border-radius:12px;padding:12px 20px;cursor:pointer;min-height:44px}
25	button:hover{background:#0058b0}
26	button.ghost{background:transparent;color:var(--accent);border:1px solid var(--hair);background:var(--surface)}
27	button.ghost:hover{background:#fff}
28	.hide{display:none!important}
29	.surf{background:var(--surface);border:1px solid var(--hair);border-radius:20px;box-shadow:0 2px 14px rgba(0,0,0,.06)}
30	/* input */
31	#input textarea{width:100%;min-height:120px;margin-top:24px;padding:16px 20px;font:15px/1.5 "Geist Mono",ui-monospace,Consolas,monospace;color:var(--ink);resize:vertical}
32	.row{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px;align-items:center}
33	.err{color:var(--fail);margin-top:16px;font-size:16px;overflow-wrap:anywhere}
34	.ex{margin-top:40px;color:var(--muted);font-size:15px}
35	.ex .row{margin-top:10px}
36	/* stages */
37	.stages{display:flex;list-style:none;padding:0;margin:32px 0 40px}
38	.stages li{flex:1;display:flex;flex-direction:column;align-items:center;gap:8px;position:relative;font-size:14px;font-weight:600;color:var(--muted);transition:color .4s var(--ease)}
39	.stages li::before{content:"";width:14px;height:14px;border-radius:50%;background:var(--page);border:2px solid #C7C7CC;z-index:1;transition:all .4s var(--ease)}
40	.stages li::after{content:"";position:absolute;top:7px;left:calc(50% + 10px);right:calc(-50% + 10px);height:2px;background:#C7C7CC;transition:background .4s var(--ease)}
41	.stages li:last-child::after{display:none}
42	.stages li.on{color:var(--ink)}
43	.stages li.on::before{background:var(--accent);border-color:var(--accent)}
44	.stages li.on::after{background:var(--accent)}
45	.stages li.cur::before{box-shadow:0 0 0 5px rgba(0,102,204,.18)}
46	.stages li.bad::before{background:var(--fail);border-color:var(--fail)}
47	.stages li.ok::before{background:var(--pass);border-color:var(--pass)}
48	.stages li.skip{color:var(--muted)}
49	/* header */
50	.meta{display:flex;flex-wrap:wrap;gap:8px 20px;margin-top:20px;color:var(--muted);font-size:15px}
51	.meta b{color:var(--ink);font-weight:600}
52	.pills{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}
53	.pill{display:inline-block;font-size:13px;font-weight:600;border-radius:99px;padding:3px 12px;border:1px solid var(--hair);color:var(--muted)}
54	.pill.verified,.pill.passed{color:var(--pass);background:rgba(31,138,59,.1);border-color:transparent}
55	.pill.failed{color:var(--fail);background:rgba(215,0,21,.08);border-color:transparent}
56	.pill.unverified{color:var(--warn);background:rgba(176,110,0,.12);border-color:transparent}
57	.pill.pop{animation:rise .5s var(--ease) both}
58	.src{margin-top:12px;font-size:15px;overflow-wrap:anywhere}
59	/* sections */
60	.blk{margin-top:48px;animation:rise .4s var(--ease) both}
61	@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
62	.steps{list-style:none;padding:0;overflow:hidden}
63	.steps li{border-top:1px solid var(--hair)}
64	.steps li:first-child{border-top:0}
65	.sr{display:grid;grid-template-columns:24px 1fr auto;gap:4px 12px;padding:14px 20px;align-items:start;list-style:none}
66	summary.sr{cursor:pointer}
67	summary.sr::-webkit-details-marker{display:none}
68	.ic{font-weight:700;text-align:center;color:#AEAEB2;font-family:"Geist Mono",ui-monospace,Consolas,monospace}
69	.ok .ic{color:var(--pass)}.no .ic{color:var(--fail)}.sk .ic{color:var(--muted)}
70	.cmd{font-size:15px;overflow-wrap:anywhere;min-width:0;white-space:pre-wrap}
71	.cmd::before{content:"$ ";color:var(--muted)}
72	.int{font-size:14px;color:var(--muted);grid-column:2}
73	.pend .cmd{display:none}.pend .int{color:var(--ink);font-size:16px;grid-column:2}
74	.pend .mt{display:none}
75	.mt{font-size:13px;color:var(--muted);text-align:right;white-space:nowrap}
76	.mt b{color:var(--warn);font-weight:600}
77	.tail{margin:0 20px 16px 56px;padding:12px 16px;background:rgba(215,0,21,.06);border-radius:12px;font-size:13px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--ink)}
78	.live .ic{color:var(--accent)}
79	/* fix */
80	.fx{padding:24px;margin-bottom:16px}
81	.fx h3{font-size:17px;font-weight:600;overflow-wrap:anywhere}
82	.bars{display:grid;grid-template-columns:auto 1fr auto;gap:6px 12px;margin:16px 0;align-items:center;font-size:13px}
83	.bars .k{color:var(--muted)}.bars .k.top{color:var(--ink);font-weight:600}
84	.trk{height:8px;border-radius:99px;background:rgba(29,29,31,.08);overflow:hidden}
85	.trk i{display:block;height:100%;width:0;background:#B7B7BC;border-radius:99px;transition:width .6s var(--ease)}
86	.trk i.top{background:var(--accent)}
87	.src2{font-size:13px;color:var(--muted);margin-bottom:8px}
88	.ba{font-size:14px;line-height:1.6}
89	.ba div{padding:6px 12px;border-radius:8px;overflow-wrap:anywhere;margin-top:6px;white-space:pre-wrap}
90	.ba .o{background:rgba(215,0,21,.07);color:var(--fail)}
91	.ba .n{background:rgba(31,138,59,.09);color:var(--pass)}
92	.why{margin-top:14px;font-size:16px}
93	.why a,.why span{font-size:14px;color:var(--muted)}
94	.why a{color:var(--accent)}
95	.note{color:var(--muted);font-size:16px}
96	/* prove */
97	.prove{padding:24px;font-size:19px;font-weight:600;letter-spacing:-.01em}
98	.prove.ok{color:var(--pass)}.prove.bad{color:var(--fail)}.prove.warn{color:var(--warn)}
99	.prove small{display:block;font-weight:400;font-size:15px;color:var(--muted);margin-top:4px;letter-spacing:0}
100	/* diff */
101	.diff{padding:16px 0;overflow-x:auto;font-size:13px;line-height:1.6}
102	.diff div{white-space:pre;padding:0 20px;min-width:max-content}
103	.diff .a{background:rgba(31,138,59,.1);color:var(--pass)}.diff .d{background:rgba(215,0,21,.07);color:var(--fail)}.diff .h{color:var(--muted)}
104	details.pr{margin-top:16px;padding:0}
105	details.pr>summary{padding:16px 20px;cursor:pointer;font-weight:600;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:44px}
106	details.pr>summary::-webkit-details-marker{display:none}
107	details.pr pre{padding:0 20px 20px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.6}
108	/* footer */
109	.cmdbox{display:flex;align-items:center;gap:12px;margin-top:16px;padding:12px 12px 12px 20px;max-width:640px}
110	.cmdbox code{flex:1;min-width:0;overflow-x:auto;white-space:nowrap;font-size:15px;padding:6px 0}
111	.cmdbox .p{color:var(--muted)}
112	.foot{margin-top:56px;padding-top:24px;border-top:1px solid var(--hair)}
113	.foot p{color:var(--muted);font-size:15px;margin-top:20px}
114	@media(max-width:720px){main{padding:24px 16px 16px}.wm{margin-bottom:28px}.stages li{font-size:12px}.cmdbox{flex-wrap:wrap}.cmdbox button{width:100%}.sr{padding:12px 14px;grid-template-columns:22px 1fr}.mt{grid-column:2;text-align:left}.tail{margin:0 14px 14px 14px}.fx{padding:18px}.pend .mt{display:none}}
115	@media(prefers-reduced-motion:reduce){.blk,.pill.pop{animation:none}.trk i{transition:none}.stages li,.stages li::before,.stages li::after{transition:none}}
116	/* bisect + prereqs */
117	.stages li{text-align:center}
118	.tl2{padding:24px 20px 20px;overflow-x:auto}
119	.tlr{display:flex;justify-content:space-between;gap:8px;position:relative;min-width:max-content;margin:0 auto}
120	.tlr::before{content:"";position:absolute;left:30px;right:30px;top:23px;height:2px;background:#D8D8DC}
121	.rel{position:relative;display:flex;flex-direction:column;align-items:center;gap:6px;min-width:64px;flex:1;font-size:12px;color:var(--muted);opacity:.35;transition:opacity .4s var(--ease)}
122	.rel i{width:18px;height:18px;border-radius:50%;background:#C7C7CC;box-shadow:0 0 0 4px var(--surface);transition:background .4s var(--ease),transform .4s var(--ease);transform:scale(.7)}
123	.rel.on{opacity:1;color:var(--ink)}
124	.rel.on i{transform:none}
125	.rel.p.on i{background:var(--pass)}.rel.f.on i{background:var(--fail)}
126	.rel.first.on{color:var(--fail);font-weight:700}
127	.rel.first.on i{box-shadow:0 0 0 4px var(--surface),0 0 0 7px rgba(215,0,21,.22)}
128	.rel b{font-weight:600;font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:12px}
129	.rel small{font-size:11px;color:var(--muted);font-weight:400}
130	.rel .tg{font-size:11px;font-weight:700;letter-spacing:.02em;color:var(--fail);min-height:14px}
131	.nt-row{margin-top:14px;font-size:13px;color:var(--muted);display:flex;align-items:center;gap:6px;flex-wrap:wrap}
132	.nt-row i{width:9px;height:9px;border-radius:50%;background:#C7C7CC;display:inline-block}
133	.verdict{padding:20px 24px;font-size:18px;font-weight:600;letter-spacing:-.01em;margin-top:14px}
134	.verdict small{display:block;font-weight:400;font-size:14px;color:var(--muted);margin-top:4px;letter-spacing:0}
135	.asm{padding:8px 0}
136	.asm ul{list-style:none;padding:0}
137	.asm li{padding:12px 24px;border-top:1px solid var(--hair);display:grid;grid-template-columns:minmax(0,auto) 1fr;gap:2px 14px;align-items:baseline}
138	.asm li:first-child{border-top:0}
139	.asm li b{font-family:"Geist Mono",ui-monospace,Consolas,monospace;font-size:15px;font-weight:600;overflow-wrap:anywhere}
140	.asm li .k{font-size:12px;color:var(--muted);font-weight:600;margin-left:8px;font-family:Geist,-apple-system,"Segoe UI",sans-serif}
141	.asm li span.r{font-size:14px;color:var(--muted);overflow-wrap:anywhere}
142	.asm .none{padding:12px 24px;color:var(--muted)}
143	.pf{padding:16px 24px;border-top:1px solid var(--hair);font-size:16px;font-weight:600}
144	.pf.ok{color:var(--pass)}.pf.bad{color:var(--warn)}
145	.pf small{display:block;font-weight:400;font-size:14px;color:var(--muted);margin-top:2px}
146	.pfa{padding:0 24px 20px}
147	@media(max-width:720px){.asm li{grid-template-columns:1fr}.tl2{padding:20px 12px 16px}.rel{min-width:56px}.asm li,.pf{padding-left:16px;padding-right:16px}.pfa{padding:0 16px 16px}.verdict{padding:16px}}
148	@media(prefers-reduced-motion:reduce){.rel,.rel i{transition:none}}
149	</style>
150	</head>
151	<body>
152	<main>
153	<div class="wm"><a href="index.html">FirstRun</a><a href="index.html">Back to the landing page</a></div>
154	
155	<section id="input" class="hide">
156	<h1>Replay a run.</h1>
157	<p class="lede">Paste the share code your terminal printed. The code decodes in this tab and never leaves it.</p>
158	<label for="code" class="hide">Share code</label>
159	<textarea id="code" class="surf" spellcheck="false" autocomplete="off" placeholder="H4sIAAAAAAAC..."></textarea>
160	<div class="row"><button id="dec" type="button">Decode</button></div>
161	<p id="err" class="err hide" role="alert"></p>
162	<div class="ex" id="ex"><span>No code yet? See a real run.</span><div class="row" id="exb"></div></div>
163	</section>
164	
165	<section id="view" class="hide">
166	<ol class="stages" id="stages" aria-label="The loop">
167	<li>Read</li><li>Plan</li><li>Run</li><li>Fix</li><li>Prove</li>
168	</ol>
169	<div id="head" class="hide">
170	<h1 id="ttl"></h1>
171	<div class="pills" id="pills"></div>
172	<div class="meta" id="meta"></div>
173	<p class="src" id="src"></p>
174	</div>
175	<div id="runb" class="blk hide"><h2 id="runh">Run</h2><ul class="steps surf" id="steps"></ul></div>
176	<div id="fixb" class="blk hide"><h2>Fix</h2><div id="fixes"></div></div>
177	<div id="provb" class="blk hide"><h2>Prove</h2><div id="prove" class="surf prove"></div></div>
178	<div id="bsb" class="blk hide"><h2>When did it break?</h2><div id="tl2" class="surf tl2"></div><div id="verd" class="surf verdict"></div></div>
179	<div id="asb" class="blk hide"><h2>What the docs assume</h2><div class="surf asm" id="asm"></div></div>
180	<div id="prb" class="blk hide"><h2>Pull request</h2><div id="diff" class="surf diff mono"></div><details class="pr surf" id="prd"><summary><span>PR description</span><button type="button" class="ghost" id="cpb">Copy</button></summary><pre id="prt"></pre></details></div>
181	<div class="foot hide" id="foot">
182	<div class="row"><button type="button" id="rep">Replay</button><button type="button" class="ghost" id="newc">Paste another code</button></div>
183	<p>Run it yourself:</p>
184	<div class="cmdbox surf"><code id="runc"><span class="p">$ </span><span id="runt"></span></code><button type="button" id="cpc" aria-label="Copy the command">Copy</button></div>
185	<p><a href="index.html">What is FirstRun?</a></p>
186	</div>
187	</section>
188	</main>
189	<script>
190	(function(){
191	"use strict";
192	var $=function(i){return document.getElementById(i)};
193	var RM=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
194	var STEP=RM?0:350,PAUSE=RM?0:500,tok=0,data=null;
195	function el(t,c,x){var e=document.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e}
196	function show(i,on){$(i).classList.toggle("hide",!on)}
197	function sleep(ms){return new Promise(function(r){ms?setTimeout(r,ms):r()})}
198	function fmt(s){s=Math.round(+s||0);if(s<60)return s+"s";return Math.floor(s/60)+"m "+(s%60)+"s"}
199	function dur(s){s=+s||0;return s<10?s.toFixed(1)+"s":fmt(s)}
200	function copy(btn,text){var o=btn.textContent;(navigator.clipboard?navigator.clipboard.writeText(text):Promise.reject()).then(function(){btn.textContent="Copied"},function(){btn.textContent="Press Ctrl+C"});setTimeout(function(){btn.textContent=o},2000)}
201	function safeUrl(u){return typeof u==="string"&&/^https?:\/\//i.test(u)}
202	
203	/* decode */
204	function b64u(s){s=s.replace(/-/g,"+").replace(/_/g,"/");while(s.length%4)s+="=";var b=atob(s),u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u}
205	function decode(raw){
206	  var c=String(raw||"").trim(),m=c.indexOf("#r=");if(m>=0)c=c.slice(m+3);c=c.replace(/\s+/g,"");
207	  if(!c)return Promise.reject(new Error("Paste a share code first."));
208	  if(typeof DecompressionStream==="undefined")return Promise.reject(new Error("This browser cannot decompress the code. Use a current Chrome, Safari or Firefox."));
209	  var bytes;try{bytes=b64u(c)}catch(e){return Promise.reject(new Error("That is not a share code. It has characters a code never holds."))}
210	  return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text().then(function(t){
211	    var o;try{o=JSON.parse(t)}catch(e){throw new Error("The code decoded but its content is not a run.")}
212	    if(!o||typeof o!=="object"||!Array.isArray(o.steps))throw new Error("The code decoded but holds no steps.");
213	    return o;
214	  },function(){throw new Error("The code is damaged or cut short. Copy it again from your terminal.")});
215	}
216	
217	/* stages */
218	var SN=["Read","Plan","Run","Fix","Prove"];
219	function stage(i,state){var li=$("stages").children[i];li.className="on"+(state?" "+state:"")}
220	function stageReset(){var S=$("stages");while(S.children.length>5)S.removeChild(S.lastChild);for(var i=0;i<5;i++)S.children[i].className=""}
221	function cur(i){for(var j=0;j<$("stages").children.length;j++)$("stages").children[j].classList.remove("cur");if(i>=0)$("stages").children[i].classList.add("cur")}
222	
223	/* render pieces */
224	function pill(t,c,pop){var p=el("span","pill "+c+(pop?" pop":""),t);return p}
225	var SL={verified:"Verified",passed:"Passed",unverified:"Unverified",failed:"Failed"};
226	function renderHead(d){
227	  $("ttl").textContent=d.title||d.target||"Untitled run";
228	  var P=$("pills");P.textContent="";
229	  var st=SL[d.status]?d.status:"unverified";
230	  P.appendChild(pill(SL[st],st,true));
231	  if(d.fixture)P.appendChild(pill("known-broken test fixture","",false));
232	  var M=$("meta");M.textContent="";
233	  function add(l,v){var s=el("span");s.appendChild(document.createTextNode(l+" "));s.appendChild(el("b",null,v));M.appendChild(s)}
234	  if(d.target)add("Target",d.target);
235	  if(d.time_to_first_success_s!=null)add("Time to first success",fmt(d.time_to_first_success_s));
236	  if(d.tool_calls!=null)add("Tool calls",String(d.tool_calls));
237	  if(d.cost_usd!=null)add("Cost","$"+(+d.cost_usd).toFixed(2)+" list price, not billed");
238	  var S=$("src");S.textContent="";
